    // Se já estiver clicando no método atual, volta para a escolha inicial
    if (method === 'pix' && isPixSelected) return;
    if (method === 'card' && !isPixSelected) return;

    if (method === 'pix') {
        if (!isPixSelected) {
            selectMethod('pix');
        } else {
            resetMethodSelection();
        }
    } else if (method === 'card') {
        if (isPixSelected) {
            selectMethod('card');
        } else {
            resetMethodSelection();
        }
    }
}

// Função auxiliar para selecionar painel correto
function selectMethod(method) {
    isPixSelected = (method === 'pix');

    // Remover destaque visual
    pixOption.classList.remove('active');
    cardOption.classList.remove('active');

    // Adicionar destaque visual
    if (isPixSelected) {
        pixOption.classList.add('active');
    } else {
        cardOption.classList.add('active');
    }

    // Mostrar apenas um painel
    if (isPixSelected) {
        pixPanel.classList.remove('hidden');
        cardPanel.classList.add('hidden');
    } else {
        cardPanel.classList.remove('hidden');
        pixPanel.classList.add('hidden');
    }

    calcularTotais(); // Recalcula valores visíveis após alternar
}

// Função para resetar seleções (caso usuário mude de ideia sem sair)
function resetMethodSelection() {
    pixPanel.classList.add('hidden');
    cardPanel.classList.add('hidden');
    pixOption.classList.remove('active');
    cardOption.classList.remove('active');
}

