    let taxPercentage = 0;

    if (installments >= 1 && installments <= 3) {
        taxPercentage = 0;
    } else if (installments === 4) {
        taxPercentage = 5;
    } else if (installments === 5) {
        taxPercentage = 10;
    }

    return currentValue * (1 + (taxPercentage / 100));
}

